import React, { useEffect, useState } from "react";

export default function AdminUserHistory({ onCancel }) {
  const [combinedHistory, setCombinedHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 20;
  const token = localStorage.getItem("authToken");

  useEffect(() => {
    fetchHistory();
  }, []);

  const fetchHistory = async () => {
    setLoading(true);
    setMessage("");

    try {
      const [withdrawRes, depositRes] = await Promise.all([
        fetch("http://localhost:8080/api/withdraw/all", {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }),
        fetch("http://localhost:8080/api/deposit/all-history", {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }),
      ]);

      if (!withdrawRes.ok || !depositRes.ok) {
        throw new Error("Failed to load data.");
      }

      const [withdrawData, depositData] = await Promise.all([
        withdrawRes.json(),
        depositRes.json(),
      ]);

      const normalizeStatus = (status) =>
        status === "APPROVED" ? "COMPLETED" : status;

      const formattedWithdraws = withdrawData.map((item) => ({
        ...item,
        type: "Withdraw",
        email: item.user?.email || item.email || "N/A",
        number: item.receiverNumber,
        date: item.requestedAt,
        status: normalizeStatus(item.status),
      }));

      const formattedDeposits = depositData.map((item) => ({
        ...item,
        type: "Deposit",
        email: item.user?.email || item.email || "N/A",
        number: item.senderNumber,
        date: item.requestedAt,
        status: normalizeStatus(item.status),
      }));

      const allCombined = [...formattedWithdraws, ...formattedDeposits].sort(
        (a, b) => new Date(b.date) - new Date(a.date)
      );

      setCombinedHistory(allCombined);
    } catch (err) {
      console.error(err);
      setMessage("Failed to load transaction history.");
    } finally {
      setLoading(false);
    }
  };

  const renderStatusBadge = (status) => {
    const colors = {
      PENDING: "bg-yellow-500",
      COMPLETED: "bg-blue-600",
      REJECTED: "bg-red-600",
    };

    return (
      <span
        className={`px-2 py-1 rounded-full text-xs font-semibold text-white ${
          colors[status] || "bg-gray-500"
        }`}
      >
        {status}
      </span>
    );
  };

  const totalPages = Math.ceil(combinedHistory.length / itemsPerPage);
  const paginatedData = combinedHistory.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  return (
    <div className="max-w-7xl mx-auto px-4 py-10">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
          📊 All User Transaction History (Combined)
        </h1>
        <button
          onClick={onCancel}
          className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-md text-sm shadow"
        >
          ← Back to Home
        </button>
      </div>

      {loading ? (
        <p className="text-center text-gray-600 text-lg">Loading...</p>
      ) : message ? (
        <p className="text-center text-red-600 font-semibold">{message}</p>
      ) : (
        <>
          <div className="bg-white shadow rounded-xl overflow-auto border mb-6">
            <table className="min-w-[1100px] w-full text-sm text-gray-700">
              <thead className="bg-gray-50 text-xs text-gray-700 uppercase sticky top-0 z-10">
                <tr>
                  <th className="px-6 py-3 text-left">#</th>
                  <th className="px-6 py-3 text-left">Type</th>
                  <th className="px-6 py-3 text-left">Email</th>
                  <th className="px-6 py-3 text-left">Amount</th>
                  <th className="px-6 py-3 text-left">Method</th>
                  <th className="px-6 py-3 text-left">Txn ID</th>
                  <th className="px-6 py-3 text-left">Number</th>
                  <th className="px-6 py-3 text-left">Status</th>
                  <th className="px-6 py-3 text-left">Date</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200 bg-white">
                {paginatedData.map((item, index) => (
                  <tr key={index} className="hover:bg-gray-50">
                    <td className="px-6 py-3">
                      {(currentPage - 1) * itemsPerPage + index + 1}
                    </td>
                    <td className="px-6 py-3">
                      {item.type === "Deposit" ? "💰 Deposit" : "🧾 Withdraw"}
                    </td>
                    <td className="px-6 py-3">{item.email}</td>
                    <td className="px-6 py-3 font-medium">
                      ৳ {Number(item.amount).toFixed(2)}
                    </td>
                    <td className="px-6 py-3">{item.method}</td>
                    <td className="px-6 py-3">{item.transactionId}</td>
                    <td className="px-6 py-3">{item.number}</td>
                    <td className="px-6 py-3">{renderStatusBadge(item.status)}</td>
                    <td className="px-6 py-3">
                      {new Date(item.date).toLocaleString()}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Pagination Controls */}
          <div className="flex justify-center items-center gap-4">
            <button
              onClick={() => setCurrentPage((p) => Math.max(p - 1, 1))}
              disabled={currentPage === 1}
              className="px-4 py-2 bg-gray-300 text-sm font-semibold rounded hover:bg-gray-400 disabled:opacity-50"
            >
              ← Previous
            </button>

            <span className="text-gray-700 font-medium">
              Page {currentPage} of {totalPages}
            </span>

            <button
              onClick={() => setCurrentPage((p) => Math.min(p + 1, totalPages))}
              disabled={currentPage === totalPages}
              className="px-4 py-2 bg-gray-300 text-sm font-semibold rounded hover:bg-gray-400 disabled:opacity-50"
            >
              Next →
            </button>
          </div>
        </>
      )}
    </div>
  );
}
